        for(int cascade=0;cascade<4;++cascade){float end=camera.Near+(farDistance-camera.Near)*Splits[cascade],centre=std::min(end,(nearDistance+end)*(1+k2)/2),radius=std::sqrt((end-centre)*(end-centre)+end*end*k2);const auto centreWorld=Add(camera.Position,Mul(forward,centre));spheres[cascade]=V4(centreWorld,radius*radius);float extent=radius*(TileSize+10.f)/TileSize;auto view=LightView(light,centreWorld);float texel=2*extent/TileSize;view._41=std::trunc(view._41/texel)*texel;view._42=std::trunc(view._42/texel)*texel;float minZ=-1-radius*1.1f,maxZ=-1+radius*1.1f+nearPlaneOffset_*10,range=std::max(.01f,maxZ-minZ);auto projection=MatrixScale(1/extent,-1/extent,1/range);projection._43=-minZ/range;const Matrix4x4 tile{.25f,0,0,0,0,-.25f,0,0,0,0,1,0,.25f+(cascade%2)*.5f,.25f+(cascade/2)*.5f,0,1};auto matrix=MatrixValues(MultiplyMatrix(MultiplyMatrix(view,projection),tile));matrices.insert(matrices.end(),matrix.begin(),matrix.end());auto* context=graphics_.Context();context->ClearState();context->OMSetRenderTargets(0,nullptr,map.Depth.Get());D3D11_VIEWPORT viewport{static_cast<float>((cascade%2)*TileSize),static_cast<float>((cascade/2)*TileSize),TileSize,TileSize,0,1};context->RSSetViewports(1,&viewport);draw({view,projection,{-light.ShadowBias/range,1,light.NormalBias*texel*3.65f,0},light});nearDistance=end;}
